Given a procedure $R$, the false discovery rate (FDR) is defined as the expectation of the false discovery proportion (FDP) with respect to the distribution $P\in \mathcal{P}$:
\begin{align}
\FDR(P,R)&= \E_{Z\sim P}[\FDP(P,R)],\:\:\: \FDP(P,R)=\frac{\sum_{i\in \cH_0} \ind{i\in R}}{1\vee |R|}.\label{equFDRFDP}
\end{align}

Compute a data-driven score function of form
\begin{equation}\label{scorefunction}
g(z)=g(z,(Z_{1},\dots,Z_{k}), (Z_{k+1},\dots,Z_{n +m})),\:\:\: z\in \mathcal{Z},
\end{equation}
which satisfies the following invariance property: for any permutation $\pi$ of $\{k+1,\dots,n+m\}$ and $z,z_1,\dots,z_{n+m}\in \mathcal{Z}$, we have
\begin{equation}\label{constrainedg}
g(z,(z_{1},\dots,z_{k}), (z_{\pi(k+1)},\dots,z_{\pi(n +m)}))=g(z,(z_{1},\dots,z_{k}), (z_{k+1},\dots,z_{n +m})).
\end{equation}

Transform the raw data into univariate scores
\begin{equation}\label{equscores}
S_i = g(Z_i; (Z_1,\dots,Z_k) , (Z_{k+1},\dots,Z_{n+m})), \quad i \in \{ k+1, \ldots,n+m\}.
\end{equation}  
Here, we assume that novelties typically have large scores.

For each test point $X_j$, generate the empirical $p$-value by comparing $S_i$ with the scores in the NTS: 
\begin{equation}\label{emppvalues}
p_j = \frac{1}{\ell+1}\left(1+\sum_{i=k+1}^{n}\ind{S_i>S_{n+j}}\right), \:\:j\in\{1,\dots,m\}.
\end{equation}

In this paper, we propose a method called AdaDetect. It is an adaptive novelty detection procedure that extends the  existing strategies described in \cite{weinstein2017power}, \cite{yang2021bonus}, \cite{mary2021semisupervised}, and \cite{bates2021testing}. It starts by splitting the null sample $(Y_1,\dots,Y_n)$  in two samples $(Y_1,\dots,Y_k)$ and $(Y_{k+1},\dots,Y_{n})$ with $k\geq 0$. To avoid cluttering our notation, we define $\ell$ as the size of the second null sample, i.e.,
$\ell=n - k.$
It proceeds with the following steps.
\begin{enumerate}
\item Compute a data-driven score function of form
\begin{equation}\label{scorefunction}
g(z)=g(z,(Z_{1},\dots,Z_{k}), (Z_{k+1},\dots,Z_{n +m})),\:\:\: z\in \mathcal{Z},
\end{equation}
which satisfies the following invariance property: for any permutation $\pi$ of $\{k+1,\dots,n+m\}$ and $z,z_1,\dots,z_{n+m}\in \mathcal{Z}$, we have
\begin{equation}\label{constrainedg}
g(z,(z_{1},\dots,z_{k}), (z_{\pi(k+1)},\dots,z_{\pi(n +m)}))=g(z,(z_{1},\dots,z_{k}), (z_{k+1},\dots,z_{n +m})).
\end{equation}
\item Transform the raw data into univariate scores
\begin{equation}\label{equscores}
S_i = g(Z_i; (Z_1,\dots,Z_k) , (Z_{k+1},\dots,Z_{n+m})), \quad i \in \{ k+1, \ldots,n+m\}.
\end{equation}  
Here, we assume that novelties typically have large scores.
\item For each test point $X_j$, generate the empirical $p$-value by comparing $S_i$ with the scores in the NTS: 
\begin{equation}\label{emppvalues}
p_j = \frac{1}{\ell+1}\left(1+\sum_{i=k+1}^{n}\ind{S_i>S_{n+j}}\right), \:\:j\in\{1,\dots,m\}.
\end{equation}
\item Apply the BH algorithm to $(p_1,\dots,p_m)$ at the target level $\alpha$.
\end{enumerate}

We will call this procedure $\mbox{AdaDetect}_\alpha$ in the sequel to emphasize the target level.

For each $i\in \cH_0$, let $\mathcal{D}_{i}$ be the distribution of $(p'_j,1\leq j\leq m)$, where
\rev{\[
\left\{\begin{array}{l}
p'_j=0,\ j\in\cH_1,\ p'_i=1/(\ell+1);\\
p'_j,\ j\in\cH_0\backslash\{i\}\ \text{are i.i.d. conditionally on }U\text{ with a common c.d.f. }F^U;\\
U=(U_1,\dots,U_{\ell+1})\text{ has i.i.d. }U(0,1)\text{ components,}
\end{array}\right.\tag{13}
\]
}
where $F^U$ denotes the discrete c.d.f. $F^U(x)=(1-U_{(\lfloor x(\ell+1)\rfloor+1)} )\ind{1/(\ell+1)\leq x<1 }+\ind{x\geq 1}$, $x\in \R$, and $U_{(1)}>\dots> U_{(\ell+1)}$ denote the order statistics of the vector $U$.
Note that the distribution $\mathcal{D}_{i}$ only depends on $i$, $m$, $\ell$ and $\cH_0$. The following general result holds.

Let 
\begin{align}
f&=\pi_0 f_0+ \pi_1 \bar f_1,\label{equ:f}\\
 \bar f_1&= m_1^{-1}\sum_{i\in \cH_1} f_i.\label{equ:f1bar}
\end{align}
Under Assumptions~\ref{as:indep} and~\ref{equ-marg}, $f_0$ is the average density of $(Z_1,\dots,Z_k)$, $\bar{f}_1$ is the average alternative density, $f$ is the average density of the test sample $(X_1,\dots,X_m)$. Similarly the average density of $(Z_{k+1},\dots,Z_{n+m})$ is $f_\gamma$ where




\begin{align}
\gamma=\frac{m_1}{\ell+m};\:\:\:\:\:\:
f_\gamma=(1-\gamma) f_0 + \gamma \bar{f}_1 =\frac{\ell}{\ell+m} f_0+ \frac{m}{\ell+m} f.\label{equfgamma}
\end{align}

Lastly, we define the density ratio
\begin{equation}\label{equLR}
\lrt(x)= \frac{\pi_1 \bar f_1(x)}{ f(x)}, \quad x\in \mathcal{Z}.
\end{equation}
Note that $\lrt(x)\in (0,1)$ for $\nu$-almost every $x\in \mathcal{Z}$ by Assumption~\ref{equ-marg}.

\rev{Recall that AdaDetect is equivalent to applying the counting knockoff on the scores which relies on an estimator $\widehat{\mathrm{FDP}}$ (Section \ref{sec:adaptiveteststat}). For each given $t$, when $\ell$ and $m$ is large, 
$\widehat{\mathrm{FDP}}(t)\approx m \:\P_{S_i\sim P_0}(S_i \ge t)/\E[|R(t)|] \approx \E[|R(t)\cap \{k+1, \ldots, n\}|]/\E[|R(t)|],$
where $R(t)$ is set of rejections at threshold $t$. The RHS is called the marginal FDR (mFDR), an error metric that is close to FDR when $|R(t)|$ is large and often used for asymptotic power analysis of FDR-controlling procedures \citep[e.g.][]{SC2007, lei2018adapt}. The following theorem derives the optimal score function among all procedures that reject hypotheses with $S_i$ above some thresholds subject to mFDR control (see \citealp{weinstein2021permutation, rosset2022optimal} for results for FDR instead of mFDR). }

Since AdaDetect is invariant under any strictly monotone transformation of the score function (see Remark~\ref{rem:invariance}), AdaDetect$^*$ can be realized as any AdaDetect procedure with a score function of the form
\begin{equation}\label{equoraclescore}
g^*= \Psi \circ \lrt, \mbox{ for some increasing continuous $\Psi:(0,1)\to {\R}$},
\end{equation}
where $\Psi$ could depend on unknown parameters. This is a crucial property of AdaDetect that enables flexible classification methods to construct score functions without concerning about the composition of nulls and novelties that may change the oracle score $\lrt$.

\begin{align}
\hat{R}_0(g)&=   k^{-1} \sum_{i=1}^{k} \ind{g(Z_i)\geq 0}, \:\:\:\:R_0(g)=\E \hat{R}_0(g) =\P_{Z\sim f_0} (g(Z)\geq 0)\label{NPexactRgamma},\\ 
\hat{R}_\gamma(g)& =(m+\ell)^{-1} \sum_{i=k+1}^{n+m} \ind{g(Z_i)<  0}, \:\:\:\:R_\gamma(g)=\E \hat{R}_\gamma(g) = (1-\gamma) (1-R_0(g))+ \gamma R_1(g),\nonumber\\
R_1(g)& =\P_{Z\sim \bar{f}_1} (g(Z)< 0),\nonumber
\end{align}
where $\gamma$, $f_0$, and $\bar{f}_1$ are defined in \eqref{equfgamma}.

\begin{align}
  \hat{g}&\in \argmin_{g \in \cG}\left\{\hat{R}_\gamma(g)\::\: \hat{R}_0(g)\leq \beta + \epsilon_0\right\},\label{defghat}
\end{align}

for some $\epsilon_0 > 0$, as well as its population version
\begin{align}
g^\sharp_\cG&\in \argmin_{g \in \cG}\left\{ R_\gamma(g)\::\:  R_0(g)\leq \beta \right\}.\label{equNP}
\end{align}

Now we move to general score functions. Let $g^*$ be any measurable function $\R^d\to \R$ in the form of \eqref{equoraclescore} and
\begin{equation}
\ol{G}_0(s) &= \P_{X\sim P_0}(g^*(X) \geq s),\quad s\in \R\label{equGbar};\end{equation}

\begin{equation}
\zeta_{r}(\eta)&=\max_{u\in [\alpha (r\vee 1)/m,\alpha]} \left\{\frac{\ol{G}_0(\ol{G}_0^{-1}(u)-2\eta) - u}{u }\right\},\quad \eta>0, r\in \{0,\dots,m\}.\label{funcdelta}
\end{equation}
Here, $\zeta_r(\cdot)$ measures the local fluctuation of $\ol{G}_0$. We suppress the dependence on $\alpha$ and $m$ to ease notation.

Furthermore, consider any data-driven score function $\hat{g}$ satisfying the condition \eqref{constrainedg} and let
\begin{align}
\hat{\eta}&=\max_{k+1\leq i\leq n+m} |\hat{g}(Z_i; (Z_1,\dots,Z_k) , (Z_{k+1},\dots,Z_{n+m}))- g^*(Z_i) |,\label{diffscore}
\end{align}
which measures the maximal discrepancy of scores in the mixed sample. In the following, $\mbox{AdaDetect}_{\alpha}$ denotes the procedure with score function $\hat{g}$ and $\mbox{AdaDetect}_{\alpha}^{*}$ denotes the procedure with score function $g^{*}$.
